{
  "tools": [
    {
      "name": "cli_execute_command",
      "integration": "cli",
      "category": "system",
      "description": "Execute a whitelisted CLI command and capture output",
      "inputSchema": {
        "type": "object",
        "properties": {
          "command": {
            "type": "string",
            "description": "CLI command to execute. Must start with a whitelisted command. Extend the whitelist via CLI_ALLOWED_COMMANDS in dmtools.env."
          },
          "workingDirectory": {
            "type": "string",
            "description": "Working directory for command execution. Defaults to repository root if not specified. Use absolute path or path relative to current directory."
          }
        },
        "required": [
          "command"
        ]
      }
    },
    {
      "name": "cli_execute_command_with_env",
      "integration": "cli",
      "category": "system",
      "description": "Execute a whitelisted CLI command with extra env vars",
      "inputSchema": {
        "type": "object",
        "properties": {
          "command": {
            "type": "string",
            "description": "The CLI command to run"
          },
          "args": {
            "type": "array",
            "description": "Arguments to pass to the command"
          },
          "env_vars": {
            "type": "object",
            "description": "Extra environment variables for the process"
          }
        },
        "required": [
          "command"
        ]
      }
    },
    {
      "name": "cli_list_allowed_commands",
      "integration": "cli",
      "category": "system",
      "description": "List all whitelisted CLI commands as a sorted array",
      "inputSchema": {
        "type": "object",
        "properties": {},
        "required": []
      }

