Future<String?> _hello(WebSocket ws, Map<String, dynamic> frame) async {
  final verdict = await _checkHello(frame);
  if (verdict != null) {
    rejectedHellos++;
    _reply(ws, {'op': 'error', 'code': verdict, 'msg': verdict});
